test('global choice beats locally attractive collision',()=>{const r=book({...base,meetings:[m('big','09:00',120,10),m('x','09:00',60,6),m('y','10:00',60,6)]});assert.equal(r.value,12);assert.deepEqual(r.bookings.map(x=>x.meeting_id),['x','y']);});
test('directed setup only between consecutive meetings',()=>{const a=m('a','09:00',30,1,'a',['p']),b=m('b','09:40',10,100,'b',['p']),c=m('c','10:00',10,1,'a',['p']);const r=book({...base,meetings:[a,b,c]});assert.deepEqual(r.bookings.map(x=>x.meeting_id),['a','b','c']);});
test('fold either offers one occurrence and nonexistent local time is omitted',()=>{const x={...m('fold','01:30',30,4),zone:'America/New_York',fold:'either'},bad={...m('bad','02:30',30,9),zone:'America/New_York'};const r=book({...base,meetings:[x,bad]});assert.equal(r.count,1);assert.equal(r.bookings[0].start,'2024-11-03T05:30:00.000Z');});
test('requirements and room blocks enforced',()=>{const dep={...m('dep','09:00',30,10),requires:['pre']};const pre=m('pre','10:00',15,2);const r=book({...base,blocks:[{room_id:'a',start:'2024-01-01T10:00:00Z',end:'2024-01-01T11:00:00Z'}],meetings:[dep,pre]});assert.equal(r.count,0);});

